// ===============================================================================
// DAEMIND SRE - PARSING DE DADOS DE ENVIO E TRANSPORTADORA
// ===============================================================================
const body = $json.body || $json;

const pedidoId = parseInt(body.pedido_id || body.id || 0, 10);
const numeroPedido = parseInt(body.numero_pedido || body.order_number || pedidoId, 10);
const codigoRastreio = (body.codigo_rastreio || body.tracking_code || body.tracking_number || '').trim();
const transportadora = (body.transportadora || body.carrier || body.forma_envio || 'Correios').trim();
let linkRastreio = body.link_rastreio || body.tracking_url || `https://rastreamento.correios.com.br/app/index.php?codigo=${codigoRastreio}`;
const previsaoEntrega = body.previsao_entrega || body.delivery_estimate || 'em breve';

return [{
  json: {
    pedido_id: pedidoId,
    numero_pedido: numeroPedido,
    codigo_rastreio: codigoRastreio,
    transportadora: transportadora,
    link_rastreio_original: linkRastreio,
    previsao_entrega: previsaoEntrega
  }
}];
